command:
cd /app && python3 - <<'PY'
p='worktree_merge.go'
s=open(p).read()
old='''\t\tcase diffmatchpatch.DiffInsert:
\t\t\tif current == nil {
\t\t\t\tcurrent = &mergeHunk{baseStart: baseIdx}
\t\t\t}
\t\t\tcurrent.newText += d.Text'''
new='''\t\tcase diffmatchpatch.DiffInsert:
\t\t\tif current == nil {
\t\t\t\tcurrent = &mergeHunk{baseStart: baseIdx, baseEnd: baseIdx}
\t\t\t}
\t\t\tcurrent.newText += d.Text'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
gofmt -w worktree_merge.go && go test . -run 'TestMergeTextEdge|TestMergeTextDebug' -count=1 -v 2>&1 | tail -30
